import streamlit as st
st.title(" Полководцы Восточного и кавказкого фронта Первой мировой войны")
st.write("Нажми на фамилию генерала, чтобы узнать его биографию:")
generals = {
    "Брусилов Алексей Алексеевич":"Генерал от кавалерии, командующий 8-й армией (1914-1915), командующий Юго-западным фронтом (1915-1917), Верховный главнокомандующий русской армии (1917).",
    "Юденич Николай Николаевич": "Генерал от инфантерии, один из самых успешных генералов русской армии, в Великой войне. Командующий Кавказской отдельной русской армией (1915-1917). Начал свою блестящую карьеру с разгрома турок, под Саракамышем, позже взял Эрзерум и Трапезунд, также Эрджиан, Огнот, Битлис и Ван.",
    "Рузский Николай Владимирович":"Генерал от инфантерии, командующий 3-й армией в ходе Галицийской битвы, (покоритель Львова), главнокомандующий войсками Северо-Западного и Северного фронтов.",
    "Иванов Николай Иудович":"Генерал от артиллерии, главнокомандующий армиями Южного (тогда, из-за отсутсвия западного фронты делились южный и северный) фронта (1914-1916 с 1915 года фронты стали Юго-Западный, Западный и Северо-Западный) руководитель действами Русской армии в Галицийской битве и Варшавско-Ивангородской операции, в 1915 году был слишком паничем из-за Горлицкого прорыва Австро-Немецких армий из-за чего, в последующем был снят с должности главнокомандующего фронта."
    }
for name, info in generals.items():
    if st.button(name):
        st.success(info)
        